topk(10,
  sum by (scenario) (
    crowdsec_alerts_grand_total{
      country=~"$country",
      as_name=~"$as_name",
      scenario=~"$scenario"
    }
  )
)

label_join(

sum by (latitude, longitude, country, as_name, as_number, ip, scenario) (
  floor(increase(
    crowdsec_alerts_total{
      country=~"$country",
      as_name=~"$as_name",
      latitude!="",
      longitude!=""
    }
    [$__range]
  ))
) > 0

,

"tooltip", " :: ", "country", "ip", "scenario"
)

